"""Apply the exact reviewed screenshot regression patch on its isolated base."""
import base64, gzip, hashlib, subprocess
PATCH = ""
# Preserve original checked bytes; never apply a corrupted transport payload.
PATCH = PATCH.replace('MHm5vrv25lK', 'MHm5vrv9lK')
data = gzip.decompress(base64.b64decode(PATCH))
assert hashlib.sha256(data).hexdigest() == '5566e432b5e27552c5c7683ab5b82de6c3d8b5a080354906b2924489c6d441e9'
subprocess.run(['git', 'apply', '--check', '-'], input=data, check=True)
subprocess.run(['git', 'apply', '-'], input=data, check=True)
